import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionUsage } from 'claude-code'

import type { Mesure } from '../types'
import { barreTexte, couleur, duree, kTokens, reinit, svgJauge } from './jauge'

const mesure = atom({ plugin: 'statusbar', key: 'mesure' } as const, null)
const modele = atom({ plugin: 'statusbar', key: 'modele' } as const, null)
const effort = atom({ plugin: 'statusbar', key: 'effort' } as const, null)
const maintenant = atom({ plugin: 'statusbar', key: 'maintenant' } as const, 0)
const surcharge = atom({ plugin: 'statusbar', key: 'surcharge' } as const, {})

const MODELES = ['opus', 'sonnet', 'haiku', 'fable']
const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max']

const versMesure = (u: Omit<SessionUsage, 'startedAt'>, startedAt: number): Mesure => ({
  startedAt,
  contextePct: u.context.percent ?? null,
  contexteTokens: u.context.tokens ?? null,
  fenetre: u.context.window,
  coutUsd: u.cost?.usd ?? null,
  quotas: u.rateLimits.map(q => ({ kind: q.kind, percentUsed: q.percentUsed, resetsAt: q.resetsAt })),
})

// /model et /effort sont le vrai changement ; si l'hôte les refuse, on réécrit chaque requête (turn.step).
async function changer($: EngineInterface, quoi: 'model' | 'effort', valeur: string) {
  const champ = quoi === 'model' ? 'modele' : 'effort'
  if (quoi === 'model') await update($, modele, () => valeur)
  else await update($, effort, () => valeur)
  try {
    if (quoi === 'model') await $.command.run({ command: 'model', args: valeur })
    else await $.command.run({ command: 'effort', args: valeur })
    await update($, surcharge, s => ({ ...s, [champ]: undefined }))
  } catch {
    await update($, surcharge, s => ({ ...s, [champ]: valeur }))
    $.ui.toast(`/${quoi} indisponible ici : ${valeur} appliqué à chaque requête par la barre`)
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const u = await $.session.usage()
    await update($, mesure, () => versMesure(u, u.startedAt))
    const t0 = await $.clock.now()
    await update($, maintenant, () => t0)
    $.clock.every(30_000, () => void $.clock.now().then(t => update($, maintenant, () => t)))
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    const avant = await read($, mesure)
    const debut = avant?.startedAt ?? (await $.clock.now())
    await update($, mesure, () => versMesure(e, debut))
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (e.agentId !== undefined) return yield* next(e)
    const s = await read($, surcharge)
    const vers = {
      ...e,
      ...(s.modele ? { model: s.modele } : {}),
      ...(s.effort ? { effort: s.effort as typeof e.effort } : {}),
    }
    await update($, modele, () => vers.model)
    await update($, effort, () => (vers.effort === undefined ? null : String(vers.effort)))
    return yield* next(vers)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const m = await read($, mesure)
    const mod = await read($, modele)
    const eff = await read($, effort)
    const now = await read($, maintenant)
    const T = $.ui.resolve(e)
    const { Box, Text, Button } = T
    const svg = 'Svg' in T ? T.Svg : undefined
    const select = 'Select' in T ? T.Select : undefined

    const jauge = (cle: string, etiquette: string, pct: number | null, infobulle: string) => {
      if (pct === null) return <Text key={cle} dimColor>{etiquette} —</Text>
      if (svg) {
        const Svg = svg
        return (
          <Svg key={cle} source={svgJauge(pct, etiquette, infobulle)} alt={`${etiquette} ${Math.round(pct)} %`} width={168} height={30} isInteractive />
        )
      }
      return (
        <Text key={cle}>
          {etiquette} <Text color={couleur(pct)}>{barreTexte(pct)}</Text> {Math.round(pct)} %
        </Text>
      )
    }

    const q5 = m?.quotas.find(q => q.kind === 'five_hour')
    const q7 = m?.quotas.find(q => q.kind === 'seven_day')
    const modeleCourant = mod ? (MODELES.find(a => mod.includes(a)) ?? mod) : undefined
    const optionsModele = [...new Set([...MODELES, ...(modeleCourant ? [modeleCourant] : [])])].map(v => ({ value: v }))
    const ctx =
      m?.contexteTokens != null ? `${kTokens(m.contexteTokens)} / ${kTokens(m.fenetre)} tokens` : `fenêtre ${kTokens(m?.fenetre ?? 0)}`

    return (
      <Box flexDirection="row" flexWrap="wrap" justifyContent="center" alignItems="center" columnGap={2} rowGap={0}>
        <Box alignSelf="center" columnGap={2}>
          {select ? (
            (() => {
              const Select = select
              return [
                <Select key="modele" label="◆" options={optionsModele} value={modeleCourant} onSelect={v => void changer($, 'model', v)} />,
                <Select key="effort" label="⚡" options={EFFORTS.map(v => ({ value: v }))} value={eff ?? undefined} onSelect={v => void changer($, 'effort', v)} />,
              ]
            })()
          ) : (
            <Text dimColor>
              {mod ?? '…'} · {eff ?? '—'}
            </Text>
          )}
        </Box>
        {jauge('ctx', 'Contexte', m?.contextePct ?? null, ctx)}
        {jauge('q5', 'Quota 5 h', q5?.percentUsed ?? null, q5 ? `Réinitialisé ${reinit(q5.resetsAt)}` : 'Aucune lecture')}
        {jauge('q7', 'Quota hebdo', q7?.percentUsed ?? null, q7 ? `Réinitialisé ${reinit(q7.resetsAt)}` : 'Aucune lecture')}
        <Box alignSelf="center" columnGap={2}>
          <Text>{m?.coutUsd != null ? `$${m.coutUsd.toFixed(2)}` : '—'}</Text>
          <Text>{m ? duree(now - m.startedAt) : '—'}</Text>
        </Box>
        <Box alignSelf="center">
        <Button
          key="compacter"
          label="Compact"
          dimColor={e.props.isWorking}
          onPress={async () => {
            if (e.props.isWorking) return void $.ui.toast('Compactage impossible pendant un tour')
            const r = await $.session.compact().catch((err: unknown) => ({ erreur: String(err) }))
            $.ui.toast('erreur' in r ? `Compactage refusé : ${r.erreur}` : 'skip' in r && r.skip ? 'Compactage annulé par un hook' : 'Session compactée')
          }}
        />
        </Box>
      </Box>
    )
  })
}

