// Du vert au rouge : les paliers servent à la fois à la couleur unie et au dégradé SVG.
const PALIERS: [number, [number, number, number]][] = [
  [0, [34, 197, 94]], // vert
  [40, [163, 230, 53]], // vert-jaune
  [60, [250, 204, 21]], // jaune
  [75, [251, 146, 60]], // orange
  [88, [244, 63, 94]], // rose-rouge
  [100, [220, 38, 38]], // rouge
]

const hex = (c: [number, number, number]) =>
  '#' + c.map(v => Math.round(v).toString(16).padStart(2, '0')).join('')

export function couleur(pct: number): string {
  const p = Math.max(0, Math.min(100, pct))
  for (let i = 1; i < PALIERS.length; i++) {
    const [p1, c1] = PALIERS[i]!
    const [p0, c0] = PALIERS[i - 1]!
    if (p <= p1) {
      const t = (p - p0) / (p1 - p0)
      const m = (a: number, b: number) => a + (b - a) * t
      return hex([m(c0[0], c1[0]), m(c0[1], c1[1]), m(c0[2], c1[2])])
    }
  }
  return hex(PALIERS[PALIERS.length - 1]![1])
}

const echapper = (s: string) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

/** Jauge SVG : piste, remplissage en dégradé sur toute la piste (la fin du remplissage a la couleur du taux), reflet, halo. */
export function svgJauge(pct: number, etiquette: string, infobulle: string): string {
  const L = 168
  const H = 30
  const x0 = 2
  const piste = L - 4
  const y = 18
  const h = 8
  const p = Math.max(0, Math.min(100, pct))
  const w = Math.max(p > 0 ? h : 0, (piste * p) / 100)
  const stops = PALIERS.map(([o, c]) => `<stop offset="${o}%" stop-color="${hex(c)}"/>`).join('')
  const fin = couleur(p)
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${L}" height="${H}" viewBox="0 0 ${L} ${H}">
<title>${echapper(infobulle)}</title>
<defs>
<linearGradient id="g" gradientUnits="userSpaceOnUse" x1="${x0}" y1="0" x2="${x0 + piste}" y2="0">${stops}</linearGradient>
<linearGradient id="reflet" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".45"/><stop offset=".6" stop-color="#fff" stop-opacity="0"/></linearGradient>
<filter id="halo" x="-20%" y="-150%" width="140%" height="400%"><feGaussianBlur stdDeviation="2.2"/></filter>
<clipPath id="c"><rect x="${x0}" y="${y}" width="${w}" height="${h}" rx="${h / 2}"/></clipPath>
</defs>
<text x="${x0}" y="12" font-family="ui-sans-serif,system-ui,sans-serif" font-size="10.5" fill="#9ca3af">${echapper(etiquette)}</text>
<text x="${L - 2}" y="12" text-anchor="end" font-family="ui-monospace,monospace" font-size="10.5" font-weight="600" fill="${fin}">${Math.round(p)} %</text>
<rect x="${x0}" y="${y}" width="${piste}" height="${h}" rx="${h / 2}" fill="#8881" stroke="#8883"/>
<rect x="${x0}" y="${y}" width="${w}" height="${h}" rx="${h / 2}" fill="${fin}" opacity=".55" filter="url(#halo)"/>
<g clip-path="url(#c)"><rect x="${x0}" y="${y}" width="${piste}" height="${h}" fill="url(#g)"/><rect x="${x0}" y="${y}" width="${piste}" height="${h}" fill="url(#reflet)"/></g>
</svg>`
}

/** Repli terminal : dix cases colorées par le taux. */
export function barreTexte(pct: number): string {
  const n = Math.round(Math.max(0, Math.min(100, pct)) / 10)
  return '█'.repeat(n) + '░'.repeat(10 - n)
}

export function duree(ms: number): string {
  const min = Math.max(0, Math.floor(ms / 60000))
  return min < 60 ? `${min} min` : `${Math.floor(min / 60)} h ${String(min % 60).padStart(2, '0')}`
}

export function reinit(iso?: string): string {
  if (!iso) return ''
  const d = new Date(iso)
  return Number.isNaN(d.getTime())
    ? ''
    : d.toLocaleString('fr-FR', { weekday: 'short', hour: '2-digit', minute: '2-digit' })
}

export const kTokens = (n: number) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n))

