export type Mesure = {
  startedAt: number
  contextePct: number | null
  contexteTokens: number | null
  fenetre: number
  coutUsd: number | null
  quotas: { kind: string; percentUsed: number; resetsAt?: string }[]
}

declare module 'claude-code' {
  interface PluginState {
    'statusbar': {
      mesure: Mesure | null
      modele: string | null
      effort: string | null
      maintenant: number
      surcharge: { modele?: string; effort?: string }
    }
  }
}
